// TypeScript Version: 4.1

/**
* Interface defining function options.
*/
interface Options {
	/**
	* Significance level (default: 0.05).
	*/
	alpha?: number;

	/**
	* Alternative hypothesis (`two-sided`, `less`, or `greater`; default: 'two-sided').
	*/
	alternative?: 'two-sided' | 'less' | 'greater';
}

/**
* Test result.
*/
interface Results {
	/**
	* Used significance level.
	*/
	alpha: number;

	/**
	* Test decision.
	*/
	rejected: boolean;

	/**
	* p-value of the test.
	*/
	pValue: number;

	/**
	* Mann–Whitney U statistic.
	*/
	U: number;

	/**
	* U value for sample x.
	*/
	U1: number;

	/**
	* U value for sample y.
	*/
	U2: number;

	/**
	* Alternative hypothesis (`two-sided`, `less`, or `greater`).
	*/
	alternative: string;

	/**
	* Name of test.
	*/
	method: string;

	/**
	* Function to print formatted output.
	*/
	print: Function;
}

/**
* Computes the Mann–Whitney U rank-sum test for two independent samples.
*
* @param x - first sample
* @param y - second sample
* @param options - function options
* @throws must provide valid options
* @returns test results
*
* @example
* var out = mannWhitneyU( [ 7, 8, 9 ], [ 1, 2, 3 ] );
* // returns {...}
*
* @example
* var out = mannWhitneyU( [ 5, 6, 7, 8 ], [ 1, 2, 3, 4 ], {
*     'alpha': 0.05,
*     'alternative': 'greater'
* });
* // returns {...}
*
* @example
* mannWhitneyU( [ 1, 2, 3 ], 'invalid' );
* // throws <TypeError>
*/
type MannWhitneyU = ( x: Array<number>, y: Array<number>, options?: Options ) => Results;

declare var mannWhitneyU: MannWhitneyU;

export = mannWhitneyU;
